      { id: "power-of-words-my-11", reference: "သုတ္တံ ၁၅:၂၃", title: "စကားလုံးများ၏ တန်ခိုး", text: "သူ၏ပါးစပ်မှ ဖြေကြားမှုကြောင့် လူသည် ဝမ်းမြောက်ခြင်းကို ရ၏။ အချိန်တန်မှ ပြောသောစကားသည် မည်ကဲ့သို့ ကောင်းမြတ်သနည်း!" },
      { id: "power-of-words-my-12", reference: "သုတ္တံ ၁၆:၂၄", title: "စကားလုံးများ၏ တန်ခိုး", text: "နူးညံ့သောစကားသည် ပျားရည်မြောင်ကဲ့သို့ ဖြစ်၍ ဝိညာဉ်ကို ချိုမြိန်စေ၍ အရိုးများကို ကျန်းမာစေ၏။" },
      { id: "power-of-words-my-13", reference: "ကောလောသဲ ၄:၆", title: "စကားလုံးများ၏ တန်ခိုး", text: "သင်တို့၏ပြောဆိုမှုသည် ဆားနှင့် ကောင်းမွန်စွာ ပြင်ဆင်ထားသကဲ့သို့ ကျေးဇူးနှင့် ညီသောအချိန်တိုင်းဖြစ်ပါစေ၊ ထိုသို့ဆိုလျှင် လူတစ်ဦးချင်းစီကို မည်ကဲ့သို့ ဖြေကြားရမည်ကို သင်တို့ သိနိုင်ကြလိမ့်မည်။" },
      { id: "power-of-words-my-14", reference: "သုတ္တံ ၁၀:၁၁", title: "စကားလုံးများ၏ တန်ခိုး", text: "ဖြောင့်မတ်သောသူ၏ ပါးစပ်သည် အသက်၏ စမ်းရေတွင်း ဖြစ်သည်။ မတရားသောသူ၏ ပါးစပ်သည် အကြမ်းဖက်မှုကို ဖုံးကွယ်ထားသည်။" },
      { id: "power-of-words-my-15", reference: "ကမ္ဘာဦး ၁:၃", title: "စကားလုံးများ၏ တန်ခိုး", text: "ဘုရားသခင်က၊ အလင်းဖြစ်ပေလော့ ဟုမိန့်တော်မူ၍ အလင်းဖြစ်လေ၏။" },
      { id: "power-of-words-my-16", reference: "ဆာလံ ၃၃:၉", title: "စကားလုံးများ၏ တန်ခိုး", text: "ဘုရားသခင်သည် မိန့်တော်မူသောအခါ ၎င်းဖြစ်ကုန်၏။ မိန့်မြွက်တော်မူ၍ ၎င်းတည်လေ၏။" },
      { id: "power-of-words-my-17", reference: "ဟေရှာ ၅၅:၁၁", title: "စကားလုံးများ၏ တန်ခိုး", text: "ကျွန်ုပ်ပါးစပ်မှ ထွက်သောစကားသည်လည်း ထိုနည်းနှင့် တူ၏။ ကျွန်ုပ်ဆီသို့ အချည်းနှီး ပြန်မလာ၊ ကျွန်ုပ်အလိုရှိသောအရာကို ဆောင်ရွက်ပြီး ကျွန်ုပ်ချေတာ်မူသောကိစ္စကို ဆောင်ရွက်ကောင်းမြတ်ရမည်ဖြစ်သည်။" },
      { id: "power-of-words-my-18", reference: "ဟေဗြဲ ၄:၁၂", title: "စကားလုံးများ၏ တန်ခိုး", text: "ဘုရားသခင်၏ နှုတ်ကပတ်တော်သည် အသက်ရှင်ပြီး အားကောင်းမြောက်သောနှုတ်ကပတ်ဖြစ်၍ နှစ်ဖက်ချွန်သောကလေးထက်ပင် ကြမ်းတမ်းသဖြင့် ဝိညာဉ်နှင့် စိတ်ကို၊ ဆစ်ဆစ်နှင့် အရိုးမှုန်ကို ဖြတ်တောက်နိုင်၍ နှလုံးသားအတွင်းရှိ တွေးခေါ်မှုနှင့် ရည်ရွယ်ချက်များကို စစ်ဆေး၏။" },
      { id: "power-of-words-my-19", reference: "မဿဲ ၈:၈", title: "စကားလုံးများ၏ တန်ခိုး", text: "တပ်မှူးငယ်သည် ဖြေ၍ မိန့်ဆိုသည်မှာ၊ သခင်၊ ကိုယ်တော် ကျွန်ုပ်အိမ်ထဲဝင်ရောက်ရန် ကျွန်ုပ် မထိုက်တန်ပါ၊ နှုတ်ကပတ်တော်ကိုသာ မိန့်မြွက်ပါ၊ သို့ဆိုလျှင် ကျွန်ုပ်ကျွန် ကောင်းမည်ဖြစ်ပါသည်ဟု ဆိုသည်။" },
      { id: "power-of-words-my-20", reference: "ယောဟန် ၆:၆၃", title: "စကားလုံးများ၏ တန်ခိုး", text: "ဝိညာဉ်သည် အသက်ပေး၏၊ ကိုယ်ခန္ဓာသည် အကျိုးမရှိ။ ငါသင်တို့အား ပြောသောစကားသည် ဝိညာဉ်ဖြစ်၍ အသက်ဖြစ်သည်။" }
